-- Triggers
CREATE TRIGGER pulse_farm_guard BEFORE INSERT OR UPDATE ON public.activity_logs FOR EACH ROW EXECUTE FUNCTION pulse_farm_guard();
CREATE TRIGGER pulse_farm_guard BEFORE INSERT OR UPDATE ON public.alerts FOR EACH ROW EXECUTE FUNCTION pulse_farm_guard('animals', 'animal_id', 'animal_treatments', 'treatment_id', 'vehicles', 'vehicle_id');
CREATE TRIGGER pulse_farm_guard BEFORE INSERT OR UPDATE ON public.animal_group_members FOR EACH ROW EXECUTE FUNCTION pulse_farm_guard('animal_groups', 'group_id', 'animals', 'animal_id');
CREATE TRIGGER pulse_farm_guard BEFORE INSERT OR UPDATE ON public.animal_groups FOR EACH ROW EXECUTE FUNCTION pulse_farm_guard();
CREATE TRIGGER pulse_farm_guard BEFORE INSERT OR UPDATE ON public.animal_health_records FOR EACH ROW EXECUTE FUNCTION pulse_farm_guard('animals', 'animal_id', 'animal_treatments', 'treatment_id', 'vet_visits', 'vet_visit_id');
CREATE TRIGGER pulse_farm_guard BEFORE INSERT OR UPDATE ON public.animal_tag_history FOR EACH ROW EXECUTE FUNCTION pulse_farm_guard('animals', 'animal_id');
